def is_palindrome(text):
    cleaned = ''
    for character in text.lower():
        if character.isalnum():
            cleaned += character
    left = 0
    right = len(cleaned) - 1
    while left < right:
        if cleaned[left] != cleaned[right]:
            return False
        left += 1
        right -= 1
    return True

