solution_code:
def eval_postfix(tokens):
    stack = []
    for token in tokens:
        if token in ('+', '-', '*'):
            if len(stack) < 2:
                raise ValueError('operator ' + token + ' needs two operands')
            right = stack.pop()
            left = stack.pop()
            if token == '+':
                stack.append(left + right)
            elif token == '-':
                stack.append(left - right)
            else:
                stack.append(left * right)
        else:
            try:
                stack.append(int(token))
            except ValueError:
                raise ValueError('unrecognized token: ' + token) from None
    if len(stack) != 1:
        raise ValueError('expression does not leave exactly one value')
    return stack[0]

