def rle_encode(text):
    if not text:
        return ''
    parts = []
    current = text[0]
    count = 1
    for char in text[1:]:
        if char == current:
            count += 1
        else:
            parts.append(current + str(count))
            current = char
            count = 1
    parts.append(current + str(count))
    return ''.join(parts)

def rle_decode(code):
    parts = []
    index = 0
    length = len(code)
    while index < length:
        char = code[index]
        index += 1
        digits = ''
        while index < length and code[index].isdigit():
            digits += code[index]
            index += 1
        if not digits:
            raise ValueError('missing run count in ' + code)
        parts.append(char * int(digits))
    return ''.join(parts)

