from functools import cmp_to_key

def largest_number(numbers):
    def compare(a, b):
        first = str(a) + str(b)
        second = str(b) + str(a)
        if first > second:
            return -1
        if first < second:
            return 1
        return 0
    ordered = sorted(numbers, key=cmp_to_key(compare))
    result = ''.join(str(number) for number in ordered)
    if result and result[0] == '0':
        return '0'
    return result

