def generate_parentheses(n):
    results = []

    def backtrack(current, opened, closed):
        if len(current) == 2 * n:
            results.append(current)
            return
        if opened < n:
            backtrack(current + '(', opened + 1, closed)
        if closed < opened:
            backtrack(current + ')', opened, closed + 1)

    backtrack('', 0, 0)
    return results

