solution_code:
def count_islands(grid):
    rows = len(grid)
    cols = len(grid[0])
    working = [row[:] for row in grid]

    def sink(r, c):
        if r < 0 or c < 0 or r >= rows or c >= cols or working[r][c] != 1:
            return
        working[r][c] = 0
        sink(r + 1, c)
        sink(r - 1, c)
        sink(r, c + 1)
        sink(r, c - 1)

    count = 0
    for r in range(rows):
        for c in range(cols):
            if working[r][c] == 1:
                count += 1
                sink(r, c)
    return count

