def decode_string(code):
    def decode(index):
        result = ''
        length = len(code)
        while index < length:
            char = code[index]
            if char.isdigit():
                digits = ''
                while index < length and code[index].isdigit():
                    digits += code[index]
                    index += 1
                inner, index = decode(index + 1)
                result += inner * int(digits)
            elif char == ']':
                return result, index + 1
            else:
                result += char
                index += 1
        return result, index
    decoded, _ = decode(0)
    return decoded

