from collections import deque

def oranges_rotting(grid):
    rows = len(grid)
    cols = len(grid[0])
    working = [row[:] for row in grid]
    queue = deque()
    fresh = 0
    for r in range(rows):
        for c in range(cols):
            if working[r][c] == 2:
                queue.append((r, c, 0))
            elif working[r][c] == 1:
                fresh += 1
    minutes = 0
    while queue:
        r, c, minute = queue.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and working[nr][nc] == 1:
                working[nr][nc] = 2
                fresh -= 1
                minutes = minute + 1
                queue.append((nr, nc, minutes))
    return minutes if fresh == 0 else -1

