def count_occurrences(text, pattern):
    m = len(pattern)
    if m == 0:
        return 0
    pi = [0] * m
    k = 0
    for i in range(1, m):
        while k and pattern[i] != pattern[k]:
            k = pi[k - 1]
        if pattern[i] == pattern[k]:
            k += 1
        pi[i] = k
    count = 0
    q = 0
    for ch in text:
        while q and ch != pattern[q]:
            q = pi[q - 1]
        if ch == pattern[q]:
            q += 1
        if q == m:
            count += 1
            q = pi[q - 1]
    return count

