def split_array_largest_sum(nums, k):
    lo, hi = max(nums), sum(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        parts = 1
        current = 0
        for x in nums:
            if current + x > mid:
                parts += 1
                current = x
            else:
                current += x
        if parts <= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

