def remove_k_digits(num, k):
    if k >= len(num):
        return '0'
    stack = []
    remaining = k
    for ch in num:
        while remaining and stack and stack[-1] > ch:
            stack.pop()
            remaining -= 1
        stack.append(ch)
    while remaining:
        stack.pop()
        remaining -= 1
    result = ''.join(stack).lstrip('0')
    return result if result else '0'

import heapq


def shortest_paths(n, edges, source):
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
    dist = [-1] * n
    dist[source] = 0
    heap = [(0, source)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        for v, w in adj[u]:
            nd = d + w
            if dist[v] == -1 or nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return dist

