import hashlib


def hash_split(items, test_fraction):
    if test_fraction < 0 or test_fraction > 1:
        raise ValueError('test_fraction must be between 0 and 1')
    threshold = int(test_fraction * 1000)
    train = []
    test = []
    for item in items:
        bucket = int(hashlib.md5(item.encode('utf-8')).hexdigest(), 16) % 1000
        if bucket < threshold:
            test.append(item)
        else:
            train.append(item)
    return (train, test)

