import math


def binary_log_loss(labels, probabilities, eps=1e-15):
    if not labels or len(labels) != len(probabilities):
        return None
    total = 0.0
    for y, p in zip(labels, probabilities):
        p = min(max(p, eps), 1 - eps)
        total += -(y * math.log(p) + (1 - y) * math.log(1 - p))
    return round(total / len(labels), 4)

def roc_auc_rank(labels, scores):
    if not labels or len(labels) != len(scores):
        return None
    n_pos = sum(1 for y in labels if y == 1)
    n_neg = len(labels) - n_pos
    if n_pos == 0 or n_neg == 0:
        return None
    order = sorted(range(len(scores)), key=lambda i: scores[i])
    ranks = [0.0] * len(scores)
    i = 0
    while i < len(order):
        j = i
        while j + 1 < len(order) and scores[order[j + 1]] == scores[order[i]]:
            j += 1
        average_rank = (i + j) / 2 + 1
        for k in range(i, j + 1):
            ranks[order[k]] = average_rank
        i = j + 1
    positive_rank_sum = sum(rank for rank, y in zip(ranks, labels) if y == 1)
    auc = (positive_rank_sum - n_pos * (n_pos + 1) / 2) / (n_pos * n_neg)
    return round(auc, 4)

import math


def entropy_gini(labels):
    if not labels:
        return None
    counts = {}
    for label in labels:
        counts[label] = counts.get(label, 0) + 1
    total = len(labels)
    entropy = 0.0
    gini = 1.0
    for count in counts.values():
        proportion = count / total
        entropy -= proportion * math.log2(proportion)
        gini -= proportion * proportion
    return {'entropy': round(entropy, 4), 'gini': round(gini, 4)}

