import math


def naive_bayes_classify(train_features, train_labels, test_features, alpha=1.0):
    if not train_features:
        raise ValueError('training data must not be empty')
    if len(train_features) != len(train_labels):
        raise ValueError('features and labels length mismatch')
    if alpha <= 0:
        raise ValueError('alpha must be positive')
    n_features = len(train_features[0])
    for row in train_features:
        if len(row) != n_features:
            raise ValueError('ragged training rows')
        if n_features == 0:
            raise ValueError('feature rows must not be empty')
    for row in test_features:
        if len(row) != n_features:
            raise ValueError('test row feature count mismatch')
    classes = sorted(set(train_labels))
    n_train = len(train_labels)
    vocabularies = [sorted({row[i] for row in train_features}) for i in range(n_features)]
    class_rows = {c: [row for row, label in zip(train_features, train_labels) if label == c] for c in classes}
    predictions = []
    for row in test_features:
        best_class = None
        best_score = None
        for c in classes:
            rows = class_rows[c]
            score = math.log(len(rows) / n_train)
            for i, value in enumerate(row):
                count = sum(1 for r in rows if r[i] == value)
                score += math.log((count + alpha) / (len(rows) + alpha * len(vocabularies[i])))
            if best_score is None or score > best_score:
                best_score = score
                best_class = c
        predictions.append(best_class)
    return predictions

