def simple_linear_regression(xs, ys):
    if not xs or len(xs) != len(ys):
        return None
    n = len(xs)
    mean_x = sum(xs) / n
    mean_y = sum(ys) / n
    sxx = sum((x - mean_x) ** 2 for x in xs)
    if sxx == 0:
        return None
    sxy = sum((x - mean_x) * (y - mean_y) for x, y in zip(xs, ys))
    slope = sxy / sxx
    intercept = mean_y - slope * mean_x
    fitted = [slope * x + intercept for x in xs]
    ss_res = sum((y - yhat) ** 2 for y, yhat in zip(ys, fitted))
    ss_tot = sum((y - mean_y) ** 2 for y in ys)
    if ss_tot == 0:
        r_squared = 1.0 if ss_res == 0 else 0.0
    else:
        r_squared = 1 - ss_res / ss_tot
    return {'slope': round(slope, 4), 'intercept': round(intercept, 4), 'r_squared': round(r_squared, 4)}

import math


def softmax_cross_entropy(logits, target_index):
    if not logits:
        raise ValueError('logits must not be empty')
    if not 0 <= target_index < len(logits):
        raise ValueError('target_index out of range')
    peak = max(logits)
    exps = [math.exp(logit - peak) for logit in logits]
    total = sum(exps)
    probabilities = [value / total for value in exps]
    loss = -math.log(probabilities[target_index])
    return {
        'probabilities': [round(p, 4) for p in probabilities],
        'loss': round(loss, 4),
    }

