def calibration_report(probabilities, labels, n_bins):
    if not isinstance(n_bins, int) or n_bins < 1:
        raise ValueError('n_bins must be a positive integer')
    if not probabilities or len(probabilities) != len(labels):
        return None
    report = []
    width = 1.0 / n_bins
    for b in range(n_bins):
        lower = b * width
        upper = (b + 1) * width
        is_last = b == n_bins - 1
        selected = [
            (p, y) for p, y in zip(probabilities, labels)
            if p >= lower and (p < upper or (is_last and p == upper))
        ]
        count = len(selected)
        if count:
            mean_predicted = sum(p for p, _ in selected) / count
            fraction_positive = sum(y for _, y in selected) / count
        else:
            mean_predicted = 0.0
            fraction_positive = 0.0
        report.append({
            'bin_lower': round(lower, 4),
            'bin_upper': round(upper, 4),
            'count': count,
            'mean_predicted': round(mean_predicted, 4),
            'fraction_positive': round(fraction_positive, 4),
        })
    return report

