import math


def knn_predict(train_features, train_labels, test_features, k):
    if not train_features:
        raise ValueError('training data must not be empty')
    if len(train_features) != len(train_labels):
        raise ValueError('features and labels length mismatch')
    if k < 1 or k > len(train_features):
        raise ValueError('k must be between 1 and the training set size')
    n_features = len(train_features[0])
    for row in train_features:
        if len(row) != n_features:
            raise ValueError('ragged training rows')
    for row in test_features:
        if len(row) != n_features:
            raise ValueError('test row feature count mismatch')
    predictions = []
    for query in test_features:
        scored = []
        for index, row in enumerate(train_features):
            distance = math.dist(query, row)
            scored.append((distance, index, train_labels[index]))
        scored.sort(key=lambda item: (item[0], item[1]))
        votes = {}
        for _, _, label in scored[:k]:
            votes[label] = votes.get(label, 0) + 1
        best = max(votes.values())
        winners = sorted(label for label, count in votes.items() if count == best)
        predictions.append(winners[0])
    return predictions

