import math


def distance_metrics(a, b):
    if not a or len(a) != len(b):
        raise ValueError('vectors must be non-empty and of equal length')
    dot = sum(x * y for x, y in zip(a, b))
    norm_a = math.sqrt(sum(x * x for x in a))
    norm_b = math.sqrt(sum(y * y for y in b))
    if norm_a == 0 or norm_b == 0:
        raise ValueError('cosine distance is undefined for a zero vector')
    euclidean = math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))
    cosine_distance = 1 - dot / (norm_a * norm_b)
    return {'euclidean': round(euclidean, 4), 'cosine_distance': round(cosine_distance, 4)}

