def kmeans_step(points, centroids):
    if not points:
        raise ValueError('points must not be empty')
    if not centroids:
        raise ValueError('centroids must not be empty')
    n_features = len(centroids[0])
    if n_features == 0:
        raise ValueError('centroid rows must not be empty')
    for row in centroids:
        if len(row) != n_features:
            raise ValueError('ragged centroids')
    for row in points:
        if len(row) != n_features:
            raise ValueError('point feature count mismatch')
    assignments = []
    for point in points:
        best_index = 0
        best_distance = None
        for index, centroid in enumerate(centroids):
            distance = sum((px - cx) ** 2 for px, cx in zip(point, centroid))
            if best_distance is None or distance < best_distance:
                best_distance = distance
                best_index = index
        assignments.append(best_index)
    new_centroids = []
    for index, centroid in enumerate(centroids):
        members = [point for point, assigned in zip(points, assignments) if assigned == index]
        if not members:
            new_centroids.append(list(centroid))
        else:
            new_centroids.append([
                round(sum(point[j] for point in members) / len(members), 4)
                for j in range(n_features)
            ])
    return {'assignments': assignments, 'centroids': new_centroids}

