import math


def logistic_gradient_step(weights, bias, features, labels, learning_rate):
    if not features:
        raise ValueError('features must not be empty')
    if len(features) != len(labels):
        raise ValueError('features and labels length mismatch')
    if learning_rate <= 0:
        raise ValueError('learning_rate must be positive')
    n_features = len(weights)
    for row in features:
        if len(row) != n_features:
            raise ValueError('feature row length mismatch')

    def sigmoid(z):
        if z >= 0:
            return 1.0 / (1.0 + math.exp(-z))
        exp_z = math.exp(z)
        return exp_z / (1.0 + exp_z)

    n = len(features)
    gradient_w = [0.0] * n_features
    gradient_b = 0.0
    for row, y in zip(features, labels):
        z = sum(w * x for w, x in zip(weights, row)) + bias
        p = sigmoid(z)
        error = p - y
        for j in range(n_features):
            gradient_w[j] += error * row[j]
        gradient_b += error
    gradient_w = [value / n for value in gradient_w]
    gradient_b /= n
    return {
        'weights': [round(w - learning_rate * g, 4) for w, g in zip(weights, gradient_w)],
        'bias': round(bias - learning_rate * gradient_b, 4),
    }

