def best_decision_stump(features, labels):
    if not features or len(features) != len(labels):
        return None
    unique_values = sorted(set(features))
    if len(unique_values) < 2:
        raise ValueError('no candidate threshold: all feature values are identical')
    thresholds = [(unique_values[i] + unique_values[i + 1]) / 2 for i in range(len(unique_values) - 1)]
    best = None
    for threshold in thresholds:
        for left_class in (0, 1):
            right_class = 1 - left_class
            error = sum(
                1 for value, label in zip(features, labels)
                if (left_class if value <= threshold else right_class) != label
            )
            candidate = (error, threshold, left_class, right_class)
            if best is None or candidate < best:
                best = candidate
    error, threshold, left_class, right_class = best
    return {
        'threshold': round(threshold, 4),
        'left_class': left_class,
        'right_class': right_class,
        'error': error,
    }

