import math


def top_k_nearest(vectors, query, k):
    if not vectors:
        raise ValueError('vectors must not be empty')
    n_features = len(vectors[0])
    if len(query) != n_features:
        raise ValueError('query length mismatch')
    if k < 1 or k > len(vectors):
        raise ValueError('k must be between 1 and len(vectors)')
    for row in vectors:
        if len(row) != n_features:
            raise ValueError('ragged vectors')
    scored = [(math.dist(query, row), index) for index, row in enumerate(vectors)]
    scored.sort(key=lambda item: (item[0], item[1]))
    return [index for _, index in scored[:k]]

