def weighted_majority_vote(votes, weights):
    if not votes:
        raise ValueError('votes must not be empty')
    if len(votes) != len(weights):
        raise ValueError('votes and weights length mismatch')
    totals = {}
    for vote, weight in zip(votes, weights):
        if weight < 0:
            raise ValueError('weights must be non-negative')
        totals[vote] = totals.get(vote, 0.0) + weight
    if sum(totals.values()) <= 0:
        raise ValueError('total weight must be positive')
    best = max(totals.values())
    winners = sorted(label for label, score in totals.items() if score == best)
    return winners[0]

