import math


def gaussian_nb_predict(train_features, train_labels, test_features, var_smoothing=1e-9):
    if not train_features:
        raise ValueError('training data must not be empty')
    if len(train_features) != len(train_labels):
        raise ValueError('features and labels length mismatch')
    n_features = len(train_features[0])
    for row in train_features:
        if len(row) != n_features:
            raise ValueError('ragged training rows')
    for row in test_features:
        if len(row) != n_features:
            raise ValueError('test row feature count mismatch')
    classes = sorted(set(train_labels))
    n_train = len(train_labels)
    statistics = {}
    for c in classes:
        rows = [row for row, label in zip(train_features, train_labels) if label == c]
        means = [sum(row[i] for row in rows) / len(rows) for i in range(n_features)]
        variances = [
            sum((row[i] - means[i]) ** 2 for row in rows) / len(rows)
            for i in range(n_features)
        ]
        statistics[c] = (len(rows) / n_train, means, variances)
    predictions = []
    for row in test_features:
        best_class = None
        best_score = None
        for c in classes:
            prior, means, variances = statistics[c]
            score = math.log(prior)
            for i, value in enumerate(row):
                variance = variances[i] + var_smoothing
                score += -0.5 * math.log(2 * math.pi * variance) - (value - means[i]) ** 2 / (2 * variance)
            if best_score is None or score > best_score:
                best_score = score
                best_class = c
        predictions.append(best_class)
    return predictions

