def fit_transform_standardize(train, test):
    if not train:
        raise ValueError('train must not be empty')
    n_features = len(train[0])
    for row in train:
        if len(row) != n_features:
            raise ValueError('ragged training rows')
    for row in test:
        if len(row) != n_features:
            raise ValueError('test row feature count mismatch')
    means = [sum(row[j] for row in train) / len(train) for j in range(n_features)]
    stds = []
    for j in range(n_features):
        variance = sum((row[j] - means[j]) ** 2 for row in train) / len(train)
        std = variance ** 0.5
        stds.append(std if std != 0 else 1.0)
    def transform(rows):
        return [
            [round((row[j] - means[j]) / stds[j], 4) for j in range(n_features)]
            for row in rows
        ]
    return {
        'mean': [round(m, 4) for m in means],
        'std': [round(s, 4) for s in stds],
        'train': transform(train),
        'test': transform(test),
    }

import random


def stratified_split(labels, test_ratio, seed=0):
    if not labels:
        raise ValueError('labels must not be empty')
    if not 0.0 <= test_ratio <= 1.0:
        raise ValueError('test_ratio must be between 0 and 1')
    random.seed(seed)
    by_class = {}
    for index, label in enumerate(labels):
        by_class.setdefault(label, []).append(index)
    train_indices = []
    test_indices = []
    for label in sorted(by_class):
        indices = by_class[label]
        indices = indices[:]
        random.shuffle(indices)
        n_test = int(round(len(indices) * test_ratio))
        test_indices.extend(indices[:n_test])
        train_indices.extend(indices[n_test:])
    return {'train': sorted(train_indices), 'test': sorted(test_indices)}

