import csv
import io


def csv_to_matrix(csv_text, label_column):
    if not csv_text or not csv_text.strip():
        raise ValueError('csv_text must not be empty')
    reader = csv.DictReader(io.StringIO(csv_text))
    rows = list(reader)
    if reader.fieldnames is None or label_column not in reader.fieldnames:
        raise ValueError('label_column not present in header')
    if not rows:
        raise ValueError('csv must contain at least one data row')
    feature_columns = [name for name in reader.fieldnames if name != label_column]
    features = []
    labels = []
    for row in rows:
        parsed = []
        for name in feature_columns:
            try:
                parsed.append(float(row[name]))
            except (TypeError, ValueError):
                raise ValueError(f'cell {row[name]!r} in column {name!r} is not a float')
        features.append(parsed)
        labels.append(row[label_column])
    return {'feature_columns': feature_columns, 'features': features, 'labels': labels}

