def rolling_mean(values, window):
    if not isinstance(window, int) or window < 1:
        raise ValueError('window must be a positive integer')
    if window > len(values):
        return []
    return [round(sum(values[i:i + window]) / window, 4) for i in range(len(values) - window + 1)]

def equal_width_bin(values, n_bins):
    if not isinstance(n_bins, int) or n_bins < 1:
        raise ValueError('n_bins must be a positive integer')
    if not values:
        return []
    low = min(values)
    high = max(values)
    if low == high:
        return [0] * len(values)
    width = (high - low) / n_bins
    bins = []
    for value in values:
        index = int((value - low) / width)
        if index >= n_bins:
            index = n_bins - 1
        bins.append(index)
    return bins

def group_mean(rows, key, value_key):
    groups = {}
    for row in rows:
        if key not in row or value_key not in row:
            raise ValueError('row is missing the grouping or value key')
        group = row[key]
        if not isinstance(group, str):
            raise ValueError('grouping key values must be strings')
        try:
            value = float(row[value_key])
        except (TypeError, ValueError):
            raise ValueError(f'value {row[value_key]!r} is not a float')
        groups.setdefault(group, []).append(value)
    return {group: round(sum(values) / len(values), 4) for group, values in sorted(groups.items())}

