import math

def cross_validate(x, y, k):
    if len(x) == 0 or len(x) != len(y):
        raise ValueError('x and y must be non-empty and of equal length')
    if k < 2 or k > len(x):
        raise ValueError('k must be at least 2 and at most len(x)')
    n = len(x)
    fold_mse = []
    for f in range(k):
        test_idx = [i for i in range(n) if i % k == f]
        train_idx = [i for i in range(n) if i % k != f]
        tx = [x[i] for i in train_idx]
        ty = [y[i] for i in train_idx]
        xbar = sum(tx) / len(tx)
        ybar = sum(ty) / len(ty)
        var = sum((v - xbar) ** 2 for v in tx)
        slope = (sum((a - xbar) * (b - ybar) for a, b in zip(tx, ty)) / var
                 if var > 0 else 0.0)
        intercept = ybar - slope * xbar
        mse = sum((slope * x[i] + intercept - y[i]) ** 2 for i in test_idx) / len(test_idx)
        fold_mse.append(round(mse, 6))
    mean = sum(fold_mse) / k
    var = sum((v - mean) ** 2 for v in fold_mse) / k
    return {'fold_mse': fold_mse, 'mean_mse': round(mean, 6),
