import math
from collections import Counter

def entropy(labels):
    if not labels:
        return 0.0
    n = len(labels)
    counts = Counter(labels)
    ent = 0.0
    for c in counts.values():
        p = c / n
        ent -= p * math.log2(p)
    return round(ent, 6)

def best_split(feature_values, labels):
    if len(feature_values) == 0 or len(feature_values) != len(labels):
        raise ValueError('feature_values and labels must be non-empty and of equal length')
    base = entropy(labels)
    best_value = None
    best_gain = None
    for v in dict.fromkeys(feature_values):
        in_labels = [l for f, l in zip(feature_values, labels) if f == v]
        out_labels = [l for f, l in zip(feature_values, labels) if f != v]
        weighted = 0.0
        if in_labels:
            weighted += (len(in_labels) / len(labels)) * entropy(in_labels)
        if out_labels:
            weighted += (len(out_labels) / len(labels)) * entropy(out_labels)
        gain = base - weighted
        if best_gain is None or gain > best_gain:
            best_gain = gain
            best_value = v
    return {'value': best_value, 'information_gain': round(best_gain, 6)}

def roc_auc(y_true, y_scores):
    if len(y_true) == 0 or len(y_true) != len(y_scores):
        raise ValueError('y_true and y_scores must be non-empty and of equal length')
    if any(v not in (0, 1) for v in y_true):
        raise ValueError('labels must be 0 or 1')
    positives = sum(y_true)
    negatives = len(y_true) - positives
    if positives == 0 or negatives == 0:
        raise ValueError('both classes must be present')
    fpr = [0.0]
    tpr = [0.0]
    for t in sorted(set(y_scores), reverse=True):
        tp = sum(1 for a, s in zip(y_true, y_scores) if a == 1 and s >= t)
        fp = sum(1 for a, s in zip(y_true, y_scores) if a == 0 and s >= t)
        tpr.append(round(tp / positives, 6))
        fpr.append(round(fp / negatives, 6))
    auc = 0.0
    for i in range(1, len(fpr)):
        auc += (fpr[i] - fpr[i - 1]) * (tpr[i] + tpr[i - 1]) / 2
    return {'fpr': fpr, 'tpr': tpr, 'auc': round(auc, 6)}

import math
import random

def _percentile(sorted_vals, q):
    if len(sorted_vals) == 1:
        return sorted_vals[0]
    pos = q * (len(sorted_vals) - 1)
    lo = math.floor(pos)
    frac = pos - lo
    hi = min(lo + 1, len(sorted_vals) - 1)
    return sorted_vals[lo] + frac * (sorted_vals[hi] - sorted_vals[lo])

def bootstrap_mean_ci(values, n_bootstrap, seed, confidence=0.95):
    if len(values) == 0:
        raise ValueError('values must be non-empty')
    if n_bootstrap < 1:
        raise ValueError('n_bootstrap must be at least 1')
    if not (0.0 < confidence < 1.0):
        raise ValueError('confidence must be strictly between 0 and 1')
    rng = random.Random(seed)
    n = len(values)
    means = []
    for _ in range(n_bootstrap):
        sample = rng.choices(values, k=n)
        means.append(sum(sample) / n)
    means.sort()
    alpha = 1.0 - confidence
    lo = _percentile(means, alpha / 2)
    hi = _percentile(means, 1 - alpha / 2)
    return {'mean': round(sum(values) / n, 6), 'lower': round(lo, 6), 'upper': round(hi, 6)}

import math

def softmax_update(weights, bias, features, target, learning_rate):
    k = len(weights)
    if k == 0 or len(bias) != k:
        raise ValueError('weights and bias must be non-empty and bias must match the number of classes')
    d = len(features)
    if d == 0:
        raise ValueError('features must be non-empty')
    if any(len(row) != d for row in weights):
        raise ValueError('weight rows must match the feature width')
    if not (0 <= target < k):
        raise ValueError('target is out of range')
    logits = [sum(w * v for w, v in zip(row, features)) + b for row, b in zip(weights, bias)]
    m = max(logits)
    exps = [math.exp(l - m) for l in logits]
    total = sum(exps)
    probs = [e / total for e in exps]
    loss = -math.log(max(probs[target], 1e-12))
    grad_b = [p - (1.0 if i == target else 0.0) for i, p in enumerate(probs)]
    new_w = [
        [w - learning_rate * g * v for w, v in zip(row, features)]
        for row, g in zip(weights, grad_b)
    ]
    new_b = [b - learning_rate * g for b, g in zip(bias, grad_b)]
    return {
        'weights': [[round(v, 6) for v in row] for row in new_w],
        'bias': [round(v, 6) for v in new_b],
        'loss': round(loss, 6),
    }

def ridge_loss_and_gradient(weights, bias, x, y, l2_lambda):
    if len(x) == 0 or len(x) != len(y):
        raise ValueError('x and y must be non-empty and of equal length')
    d = len(weights)
    if d == 0:
        raise ValueError('weights must be non-empty')
    if any(len(row) != d for row in x):
        raise ValueError('rows must match the weight width')
    n = len(x)
    preds = [sum(w * v for w, v in zip(weights, row)) + bias for row in x]
    residuals = [p - t for p, t in zip(preds, y)]
    mse = sum(r * r for r in residuals) / n
    loss = mse + l2_lambda * sum(w * w for w in weights)
    grad_w = [
        2.0 * sum(r * row[j] for r, row in zip(residuals, x)) / n + 2 * l2_lambda * weights[j]
        for j in range(d)
    ]
    grad_b = 2.0 * sum(residuals) / n
    return {
        'loss': round(loss, 6),
        'weight_grad': [round(g, 6) for g in grad_w],
        'bias_grad': round(grad_b, 6),
    }

import math

def top_k_similar(query_vector, embeddings, k):
    if len(query_vector) == 0:
        raise ValueError('query vector must be non-empty')
    qn = math.sqrt(sum(v * v for v in query_vector))
    if qn == 0:
        raise ValueError('query vector must have a non-zero norm')
    if k < 1:
        raise ValueError('k must be at least 1')
    results = []
    for name, vec in embeddings.items():
        if len(vec) != len(query_vector):
            raise ValueError('embedding width mismatch for ' + str(name))
        vn = math.sqrt(sum(v * v for v in vec))
        if vn == 0:
            continue
        dot = sum(a * b for a, b in zip(query_vector, vec))
        results.append((name, round(dot / (qn * vn), 6)))
    results.sort(key=lambda item: (-item[1], item[0]))
    return [{'name': name, 'similarity': sim} for name, sim in results[:k]]

def pagerank(links, damping=0.85, iterations=100, tolerance=1e-10):
    if damping < 0.0 or damping >= 1.0:
        raise ValueError('damping must be in [0, 1)')
    if iterations < 1:
        raise ValueError('iterations must be at least 1')
    nodes = set(links) | {t for outs in links.values() for t in outs}
    if not nodes:
        return {}
    node_list = sorted(nodes, key=str)
    n = len(node_list)
    idx = {node: i for i, node in enumerate(node_list)}
    out = [links.get(node, []) for node in node_list]
    pr = [1.0 / n] * n
    for _ in range(iterations):
        dangling = sum(pr[i] for i in range(n) if len(out[i]) == 0)
        new = [(1 - damping) / n + damping * dangling / n] * n
        for i in range(n):
            if out[i]:
                share = damping * pr[i] / len(out[i])
                for tgt in out[i]:
                    new[idx[tgt]] += share
        shift = max(abs(new[i] - pr[i]) for i in range(n))
        pr = new
        if shift < tolerance:
            break
    return {node: round(pr[idx[node]], 6) for node in node_list}

def fit_gradient_stumps(x, y, n_estimators, learning_rate):
    if len(x) == 0 or len(x) != len(y):
        raise ValueError('x and y must be non-empty and of equal length')
    if n_estimators < 1:
        raise ValueError('n_estimators must be at least 1')
    if learning_rate <= 0:
        raise ValueError('learning_rate must be positive')
    n = len(x)
    init = sum(y) / n
    preds = [init] * n
    stumps = []
    for _ in range(n_estimators):
        residuals = [yi - pi for yi, pi in zip(y, preds)]
        uniques = sorted(set(x))
        candidates = [(a + b) / 2 for a, b in zip(uniques, uniques[1:])]
        if candidates:
            best = None
            for t in candidates:
                left = [r for xi, r in zip(x, residuals) if xi <= t]
                right = [r for xi, r in zip(x, residuals) if xi > t]
                lv = sum(left) / len(left)
                rv = sum(right) / len(right)
                sse = sum((r - lv) ** 2 for r in left) + sum((r - rv) ** 2 for r in right)
                if best is None or sse < best[0]:
                    best = (sse, t, lv, rv)
            sse, t, lv, rv = best
        else:
            t = uniques[0]
            lv = rv = sum(residuals) / n
        stumps.append({'threshold': round(t, 6),
                       'left_value': round(lv, 6),
                       'right_value': round(rv, 6)})
        for i in range(n):
            preds[i] += learning_rate * (lv if x[i] <= t else rv)
    mse = sum((yi - pi) ** 2 for yi, pi in zip(y, preds)) / n
    return {'init': round(init, 6), 'stumps': stumps, 'mse': round(mse, 6)}

