def kmeans_lloyd(points, k, max_iter=100, tolerance=1e-9):
    if len(points) == 0:
        raise ValueError('points must be non-empty')
    if k < 1 or k > len(points):
        raise ValueError('k must be between 1 and the number of points')
    dim = len(points[0])
    if dim == 0:
        raise ValueError('points must have at least one dimension')
    if any(len(p) != dim for p in points):
        raise ValueError('all points must have the same dimension')
    centroids = [list(points[i]) for i in range(k)]
    labels = [0] * len(points)
    iterations = 0
    for it in range(1, max_iter + 1):
        new_labels = []
        for p in points:
            best_j = 0
            best_d = None
            for j in range(k):
                d = sum((p[t] - centroids[j][t]) ** 2 for t in range(dim))
                if best_d is None or d < best_d:
                    best_d = d
                    best_j = j
            new_labels.append(best_j)
        new_centroids = []
        for j in range(k):
            members = [points[i] for i in range(len(points)) if new_labels[i] == j]
            if members:
                new_centroids.append([sum(m[t] for m in members) / len(members) for t in range(dim)])
            else:
                new_centroids.append(list(centroids[j]))
        shift = max(abs(new_centroids[j][t] - centroids[j][t])
                    for j in range(k) for t in range(dim))
        centroids = new_centroids
        labels = new_labels
        iterations = it
        if shift < tolerance:
            break
    return {'centroids': [[round(v, 6) for v in c] for c in centroids],
            'labels': labels, 'iterations': iterations}

