import math
import re

def tfidf_retrieve(documents, query, top_k):
    if top_k < 1:
        raise ValueError('top_k must be at least 1')
    if len(documents) == 0:
        return []
    token_re = re.compile(r'[a-z0-9]+')
    def tokenize(text):
        return token_re.findall(text.lower())
    docs_tokens = [tokenize(d) for d in documents]
    n_docs = len(documents)
    df = {}
    for toks in docs_tokens:
        for tok in set(toks):
            df[tok] = df.get(tok, 0) + 1
    def vector(tokens):
        counts = {}
        for t in tokens:
            counts[t] = counts.get(t, 0) + 1
        return {t: c * math.log(n_docs / df[t]) for t, c in counts.items() if df.get(t, 0) > 0}
    doc_vecs = [vector(t) for t in docs_tokens]
    q_vec = vector(tokenize(query))
    def norm(v):
        return math.sqrt(sum(w * w for w in v.values()))
    qn = norm(q_vec)
    if qn == 0:
        return []
    scored = []
    for i, dv in enumerate(doc_vecs):
        dn = norm(dv)
        if dn == 0:
            continue
        dot = sum(w * dv.get(t, 0.0) for t, w in q_vec.items())
        sim = dot / (qn * dn)
        if sim > 0:
            scored.append((i, round(sim, 6)))
    scored.sort(key=lambda item: (-item[1], item[0]))
    return [{'index': i, 'score': s} for i, s in scored[:top_k]]

def learning_curve(x_train, y_train, x_val, y_val, sizes):
    if len(x_train) == 0 or len(x_train) != len(y_train):
        raise ValueError('x_train and y_train must be non-empty and of equal length')
    if len(x_val) != len(y_val):
        raise ValueError('x_val and y_val must be of equal length')
    if len(sizes) == 0:
        raise ValueError('sizes must be non-empty')
    results = []
    for size in sizes:
        if not isinstance(size, int) or isinstance(size, bool) or size < 1 or size > len(x_train):
            raise ValueError('each size must be an integer in [1, len(x_train)]')
        tx = x_train[:size]
        ty = y_train[:size]
        xbar = sum(tx) / size
        ybar = sum(ty) / size
        var = sum((v - xbar) ** 2 for v in tx)
        slope = (sum((a - xbar) * (b - ybar) for a, b in zip(tx, ty)) / var
                 if var else 0.0)
        intercept = ybar - slope * xbar
        def mse(xs, ys):
            if not xs:
                return None
            return round(sum((slope * a + intercept - b) ** 2 for a, b in zip(xs, ys)) / len(xs), 6)
        results.append({'size': size, 'train_mse': mse(tx, ty), 'val_mse': mse(x_val, y_val)})
    return results

