def precision_recall_auc(y_true, y_scores):
    if len(y_true) == 0 or len(y_true) != len(y_scores):
        raise ValueError('y_true and y_scores must be non-empty and of equal length')
    if any(v not in (0, 1) for v in y_true):
        raise ValueError('labels must be 0 or 1')
    positives = sum(y_true)
    if positives == 0:
        raise ValueError('at least one positive label is required')
    points = [[0.0, 1.0]]
    for t in sorted(set(y_scores), reverse=True):
        tp = sum(1 for a, s in zip(y_true, y_scores) if a == 1 and s >= t)
        fp = sum(1 for a, s in zip(y_true, y_scores) if a == 0 and s >= t)
        recall = tp / positives
        precision = tp / (tp + fp) if tp + fp > 0 else 1.0
        points.append([round(recall, 6), round(precision, 6)])
    auc = 0.0
    for i in range(1, len(points)):
        dr = points[i][0] - points[i - 1][0]
        auc += dr * (points[i][1] + points[i - 1][1]) / 2
    return {'points': points, 'auc': round(auc, 6)}

