    if len(uniques) < 2:
        raise ValueError('x must contain at least two unique values')
    candidates = [(a + b) / 2 for a, b in zip(uniques, uniques[1:])]
    best = None
    for t in candidates:
        left = [v for xi, v in zip(x, y) if xi <= t]
        right = [v for xi, v in zip(x, y) if xi > t]
        left_mean = sum(left) / len(left)
        right_mean = sum(right) / len(right)
        sse = (sum((v - left_mean) ** 2 for v in left)
               + sum((v - right_mean) ** 2 for v in right))
        if best is None or sse < best[0]:
            best = (sse, t, left_mean, right_mean)
    sse, t, left_mean, right_mean = best
    return {'threshold': round(t, 6), 'left_mean': round(left_mean, 6),
            'right_mean': round(right_mean, 6), 'sse': round(sse, 6)}

