import random

def bias_variance_decomposition(x_train, y_train, x_test, y_test, n_bootstrap, seed):
    if len(x_train) == 0 or len(x_train) != len(y_train):
        raise ValueError('x_train and y_train must be non-empty and of equal length')
    if len(x_test) == 0 or len(x_test) != len(y_test):
        raise ValueError('x_test and y_test must be non-empty and of equal length')
    if n_bootstrap < 1:
        raise ValueError('n_bootstrap must be at least 1')
    rng = random.Random(seed)
    n = len(x_train)
    preds_per_point = [[] for _ in x_test]
    for _ in range(n_bootstrap):
        idxs = [rng.randrange(n) for _ in range(n)]
        sx = [x_train[i] for i in idxs]
        sy = [y_train[i] for i in idxs]
        xbar = sum(sx) / n
        ybar = sum(sy) / n
        var = sum((v - xbar) ** 2 for v in sx)
        slope = (sum((a - xbar) * (b - ybar) for a, b in zip(sx, sy)) / var
                 if var else 0.0)
        intercept = ybar - slope * xbar
        for j, tx in enumerate(x_test):
            preds_per_point[j].append(slope * tx + intercept)
    bias_sq = 0.0
    var_ = 0.0
    mse = 0.0
    for j in range(len(x_test)):
        ps = preds_per_point[j]
        mp = sum(ps) / len(ps)
        bias_sq += (mp - y_test[j]) ** 2
        var_ += sum((p - mp) ** 2 for p in ps) / len(ps)
        mse += sum((p - y_test[j]) ** 2 for p in ps) / len(ps)
    m = len(x_test)
    return {'bias_squared': round(bias_sq / m, 6),
            'variance': round(var_ / m, 6),
            'expected_mse': round(mse / m, 6)}

