    tokens = _WORD_RE.findall(text.lower() if text else "")
    return sum(1 for token in tokens if token not in known)

import re

_PLACEHOLDER_RE = re.compile(r"\{\{\s*([A-Za-z_][A-Za-z0-9_]*)\s*\}\}")


def render_prompt(template, values):
    sentinel_open, sentinel_close = "\x00", "\x01"
    working = template.replace("{{{{", sentinel_open).replace("}}}}", sentinel_close)

    def _replace(match):
        name = match.group(1)
        if name not in values:
            raise KeyError(name)
        return str(values[name])

    working = _PLACEHOLDER_RE.sub(_replace, working)
    return working.replace(sentinel_open, "{{").replace(sentinel_close, "}}")

