def pack_context(items, budget):
    if budget < 0:
        raise ValueError('budget must be non-negative')
    for item in items:
        if item['tokens'] < 0:
            raise ValueError('tokens must be non-negative')
    ordered = sorted(items, key=lambda item: (-item['priority'], item['id']))
    remaining = budget
    selected = []
    for item in ordered:
        if item['tokens'] <= remaining:
            selected.append(item['id'])
            remaining -= item['tokens']
    return selected

import json
import re

def repair_json(text):
    if not isinstance(text, str) or not text.strip():
        raise ValueError('text must be a non-empty string')

    def attempt(candidate):
        try:
            return True, json.loads(candidate)
        except ValueError:
            return False, None

    s = text.strip()
    ok, value = attempt(s)
    if ok:
        return value
    if s.startswith('```'):
        newline = s.find('\n')
        s = s[newline + 1:] if newline != -1 else s[3:]
        if s.rstrip().endswith('```'):
            s = s.rstrip()[:-3]
        s = s.strip()
        ok, value = attempt(s)
        if ok:
            return value
    for open_ch, close_ch in (('{', '}'), ('[', ']')):
        start = s.find(open_ch)
        end = s.rfind(close_ch)
        if start != -1 and end > start:
            trimmed = s[start:end + 1]
            ok, value = attempt(trimmed)
            if ok:
                return value
            s = trimmed
            break
    stripped = re.sub(r',(\s*[}\]])', r'\1', s)
    if stripped != s:
        ok, value = attempt(stripped)
        if ok:
            return value
        s = stripped
    if '"' not in s:
        quoted = s.replace("'", '"')
        ok, value = attempt(quoted)
        if ok:
            return value
    raise ValueError('unrepairable JSON')

