import math
from collections import Counter

def _tokens(text):
    return ' '.join(text.lower().split()).split()

def exact_match(prediction, reference):
    return ' '.join(prediction.lower().split()) == ' '.join(reference.lower().split())

def token_f1(prediction, reference):
    pred = _tokens(prediction)
    ref = _tokens(reference)
    if not pred and not ref:
        return 1.0
    if not pred or not ref:
        return 0.0
    common = sum((Counter(pred) & Counter(ref)).values())
    if common == 0:
        return 0.0
    precision = common / len(pred)
    recall = common / len(ref)
    return round(2 * precision * recall / (precision + recall), 4)

def pass_at_k(n, c, k):
    if n <= 0 or k <= 0 or k > n:
        raise ValueError('require n >= 1 and 1 <= k <= n')
    if c <= 0:
        return 0.0
    if c >= n or (n - c) < k:
        return 1.0
    return round(1 - math.comb(n - c, k) / math.comb(n, k), 4)

import re

def grounding_check(answer, context, threshold=0.5):
    answer_tokens = set(re.findall(r'[a-z0-9]+', answer.lower()))
    if not answer_tokens:
        return (0.0, False)
    context_tokens = set(re.findall(r'[a-z0-9]+', context.lower()))
    score = round(len(answer_tokens & context_tokens) / len(answer_tokens), 4)
    return (score, score >= threshold)

