import re
from collections import Counter

def _tokens(text):
    return re.findall(r'[a-z0-9]+', text.lower())

def top_k_documents(query, documents, k):
    if k < 1:
        raise ValueError('k must be at least 1')
    query_counts = Counter(_tokens(query))
    if not query_counts:
        return []
    query_norm = sum(value * value for value in query_counts.values()) ** 0.5
    scored = []
    for index, doc in enumerate(documents):
        doc_counts = Counter(_tokens(doc))
        if not doc_counts:
            continue
        dot = sum(query_counts[token] * doc_counts[token] for token in query_counts if token in doc_counts)
        if dot == 0:
            continue
        doc_norm = sum(value * value for value in doc_counts.values()) ** 0.5
        scored.append((index, round(dot / (query_norm * doc_norm), 4)))
    scored.sort(key=lambda pair: (-pair[1], pair[0]))
    return scored[:k]

