def validate_tool_args(schema, args):
    if not isinstance(args, dict):
        raise ValueError('args must be a dict')
    properties = schema.get('properties', {})
    required = schema.get('required', [])
    additional = schema.get('additionalProperties', True)
    errors = []
    for name in required:
        if name not in args:
            errors.append(f'missing required argument: {name}')

    def type_ok(value, expected):
        if expected == 'string':
            return isinstance(value, str)
        if expected == 'boolean':
            return isinstance(value, bool)
        if expected == 'integer':
            return isinstance(value, int) and not isinstance(value, bool)
        if expected == 'number':
            return isinstance(value, (int, float)) and not isinstance(value, bool)
        if expected == 'array':
            return isinstance(value, list)
        if expected == 'object':
            return isinstance(value, dict)
        return True

    for name, spec in properties.items():
        if name in args and not type_ok(args[name], spec.get('type')):
            errors.append(f"argument {name} must be of type {spec.get('type')}")
    if not additional:
        for name in args:
            if name not in properties:
                errors.append(f'unexpected argument: {name}')
    return (not errors, sorted(errors))

