def call_with_backoff(fn, max_attempts, base_delay=1.0, max_delay=30.0, retry_exceptions=(Exception,), sleep_fn=None):
    if not isinstance(max_attempts, int) or isinstance(max_attempts, bool) or max_attempts < 1:
        raise ValueError('max_attempts must be a positive integer')
    if base_delay < 0 or max_delay < 0:
        raise ValueError('delays must be non-negative')
    delays = []
    for attempt in range(1, max_attempts + 1):
        try:
            result = fn()
            return {'ok': True, 'result': result, 'error': None, 'attempts': attempt, 'delays': delays}
        except retry_exceptions as exc:
            if attempt == max_attempts:
                return {'ok': False, 'result': None, 'error': str(exc), 'attempts': attempt, 'delays': delays}
            delay = min(max_delay, base_delay * (2 ** (attempt - 1)))
            delays.append(delay)
            if sleep_fn is not None:
                sleep_fn(delay)

