def trim_conversation(messages, max_tokens):
    if max_tokens < 0:
        raise ValueError('max_tokens must be non-negative')

    def cost(message):
        return len(message['content'].split())

    used = sum(cost(m) for m in messages if m.get('role') == 'system')
    keep = [m.get('role') == 'system' for m in messages]
    for index in range(len(messages) - 1, -1, -1):
        message = messages[index]
        if message.get('role') == 'system':
            continue
        needed = cost(message)
        if used + needed <= max_tokens:
            keep[index] = True
            used += needed
    return [m for m, kept in zip(messages, keep) if kept]

