import hashlib
import json

def embedding_cache_key(text, model, dimensions):
    if not isinstance(dimensions, int) or isinstance(dimensions, bool) or dimensions < 1:
        raise ValueError('dimensions must be a positive integer')
    payload = json.dumps({'text': text, 'model': model, 'dimensions': dimensions}, sort_keys=True, separators=(',', ':'), ensure_ascii=False)
    return hashlib.sha256(payload.encode('utf-8')).hexdigest()

def get_or_compute(cache, text, model, dimensions, compute_fn):
    key = embedding_cache_key(text, model, dimensions)
    if key in cache:
        return cache[key], True
    embedding = compute_fn(text)
    cache[key] = embedding
    return embedding, False

import re

_PATTERNS = [
    ('ignore_instructions', r'\bignore\s+(all\s+|any\s+|the\s+)?(previous|prior|earlier|above|preceding)\s+(instructions|directives|prompts|rules)\b'),
    ('role_override', r'\b(you are now|act as|pretend (to be|you are)|from now on,? you|roleplay as)\b'),
    ('prompt_probe', r'\b(system prompt|hidden instructions|initial prompt|reveal (your|the) (prompt|instructions)|repeat the words above)\b'),
    ('delimiter_injection', r'(<\s*/?\s*(system|assistant|user)\s*>|\[/?INST\]|<\|im_start\|>|###\s*(system|instruction))'),
    ('data_exfiltration', r'\b(exfiltrate|send (all|the) (data|contents|credentials|secrets)|forward (the|these) (credentials|secrets|keys)|email the)\b'),
]

def detect_injection(text):
    if not isinstance(text, str):
        raise ValueError('text must be a string')
    signals = set()
    for name, pattern in _PATTERNS:
        if re.search(pattern, text, re.IGNORECASE):
            signals.add(name)
    ordered = sorted(signals)
    return {'flagged': bool(ordered), 'signals': ordered}

