solution_code:
def _validate_port(text, entry):
    try:
        port = int(text)
    except ValueError:
        raise ValueError(f'malformed port in entry: {entry}')
    if port < 1 or port > 65535:
        raise ValueError(f'port out of range in entry: {entry}')
    return port

def _parse_port_entry(entry):
    text = entry.strip()
    if '/' in text:
        text, protocol = text.split('/', 1)
        if protocol not in ('tcp', 'udp'):
            raise ValueError(f'unsupported protocol in port entry: {entry}')
    parts = text.split(':')
    if len(parts) == 1:
        _validate_port(parts[0], entry)
        return None
    if len(parts) == 2:
        host_ip, host_port = '0.0.0.0', parts[0]
    elif len(parts) == 3:
        host_ip, host_port = parts[0], parts[1]
    else:
        raise ValueError(f'malformed port entry: {entry}')
    return (host_ip, _validate_port(host_port, entry))

def find_port_conflicts(compose_spec):
    bindings = {}
    for service, config in compose_spec.items():
        ports = (config or {}).get('ports', [])
        if not isinstance(ports, list):
            raise ValueError(f'ports for service {service} must be a list')
        for entry in ports:
            if not isinstance(entry, str):
                raise ValueError('port entries must be strings')
            parsed = _parse_port_entry(entry)
            if parsed is None:
                continue
            bindings.setdefault(parsed, set()).add(service)
    conflicts = [
        {'host_ip': host_ip, 'port': port, 'services': sorted(services)}
        for (host_ip, port), services in bindings.items()
        if len(services) > 1
    ]
    conflicts.sort(key=lambda item: (item['host_ip'], item['port']))
    return conflicts

