solution_code:
def scope_granted(granted, scope):
    parts = scope.split(':')
    if len(parts) != 2 or not all(parts):
        raise ValueError('scope must be "resource:action" with two non-empty parts')
    resource, action = parts
    for grant in granted:
        if grant == '*:*':
            return True
        grant_parts = grant.split(':')
        if len(grant_parts) != 2 or not all(grant_parts):
            continue
        g_resource, g_action = grant_parts
        if g_resource in ('*', resource) and g_action in ('*', action):
            return True
    return False

def check_tool_access(granted, tool):
    required = tool.get('scopes', [])
    missing = [scope for scope in required if not scope_granted(granted, scope)]
    return {'allowed': not missing, 'missing': missing}

def find_unused_grants(granted, tools):
    required_scopes = [scope for tool in tools for scope in tool.get('scopes', [])]
    unused = [grant for grant in set(granted) if not any(scope_granted([grant], scope) for scope in required_scopes)]
    return sorted(unused)

