import hashlib
import re

_TOKEN_RE = re.compile(r"[a-z0-9]+")
_DIM = 64


def _tokens(text):
    return _TOKEN_RE.findall(str(text).lower())


def _hash_vector(text):
    vec = [0.0] * _DIM
    for tok in _tokens(text):
        digest = hashlib.md5(tok.encode("utf-8")).hexdigest()
        vec[int(digest, 16) % _DIM] += 1.0
    return vec


def _cosine(a, b):
    na = sum(x * x for x in a) ** 0.5
    nb = sum(x * x for x in b) ** 0.5
    if na == 0.0 or nb == 0.0:
        return 0.0
    return sum(x * y for x, y in zip(a, b)) / (na * nb)


def retrieve_with_mmr(documents, query, top_k=3, mmr_lambda=0.7):
    if top_k <= 0:
        return []
    lam = min(1.0, max(0.0, mmr_lambda))
    vecs = [_hash_vector(doc.get("text", "")) for doc in documents]
    qvec = _hash_vector(query)
    relevance = [_cosine(qvec, v) for v in vecs]
    selected = []
    remaining = list(range(len(documents)))
    while remaining and len(selected) < top_k:
        best_i = None
        best_score = None
        for i in remaining:
            if selected:
                max_sim = max(_cosine(vecs[i], vecs[j]) for j in selected)
            else:
                max_sim = 0.0
            score = lam * relevance[i] - (1.0 - lam) * max_sim
            if best_score is None or score > best_score + 1e-12:
                best_score = score
                best_i = i
        selected.append(best_i)
        remaining.remove(best_i)
    return [documents[i]["id"] for i in selected]

