import math


class VectorStore:
    def __init__(self, dim):
        if not isinstance(dim, int) or isinstance(dim, bool) or dim <= 0:
            raise ValueError("dim must be a positive integer")
        self.dim = dim
        self._vectors = {}
        self._deleted = set()

    def _validate(self, vector, label="vector"):
        try:
            vec = [float(x) for x in vector]
        except (TypeError, ValueError) as exc:
            raise ValueError(f"{label} must be a list of numbers") from exc
        if len(vec) != self.dim:
            raise ValueError(f"expected {label} of dim {self.dim}, got {len(vec)}")
        return vec

    def upsert(self, doc_id, vector):
        vec = self._validate(vector)
        self._vectors[doc_id] = vec
        self._deleted.discard(doc_id)
        return True

    def delete(self, doc_id):
        if doc_id in self._vectors and doc_id not in self._deleted:
            self._deleted.add(doc_id)
            return True
        return False

    def search(self, query_vector, top_k=5):
        if top_k <= 0:
            return []
        q = self._validate(query_vector, "query_vector")
        qn = math.sqrt(sum(x * x for x in q))
        if qn == 0.0:
            return []
        nq = [x / qn for x in q]
        scored = []
        for doc_id, vec in self._vectors.items():
            if doc_id in self._deleted:
                continue
            vn = math.sqrt(sum(x * x for x in vec))
            if vn == 0.0:
                continue
            score = sum(a * b for a, b in zip(nq, (x / vn for x in vec)))
            scored.append((doc_id, round(score, 4)))
        scored.sort(key=lambda item: (-item[1], item[0]))
        return scored[:top_k]

    def compact(self):
        count = len(self._deleted)
        for doc_id in list(self._deleted):
            self._vectors.pop(doc_id, None)
        self._deleted.clear()
        return count

    def stats(self):
        total = len(self._vectors)
        deleted = len(self._deleted)
        return {"dim": self.dim, "live": total - deleted, "deleted": deleted, "total": total}

import json


def _result(status, answer, steps, tokens_used, tool_calls):
    return {"status": status, "answer": answer, "steps": steps,
            "tokens_used": tokens_used, "tool_calls": list(tool_calls)}


def run_agent(model, tools, task, max_steps=6, max_tokens=2000):
    messages = [{"role": "user", "content": task}]
    tokens_used = 0
    steps = 0
    tool_calls = []
    while steps < max_steps:
        steps += 1
        try:
            resp = model(messages)
        except Exception:
            return _result("model_error", None, steps, tokens_used, tool_calls)
        if not isinstance(resp, dict):
            return _result("model_error", None, steps, tokens_used, tool_calls)
        tokens = resp.get("tokens")
        if not isinstance(tokens, int) or isinstance(tokens, bool):
            tokens = (len(json.dumps(resp, default=str)) // 4) + 1
        tokens_used += tokens
        if tokens_used > max_tokens:
            return _result("budget_exceeded", None, steps, tokens_used, tool_calls)
        rtype = resp.get("type")
        if rtype == "final":
            return _result("completed", resp.get("content"), steps, tokens_used, tool_calls)
        if rtype == "tool_call":
            name = resp.get("tool")
            args = resp.get("arguments", {})
            tool_calls.append(str(name))
            if name not in tools or not isinstance(args, dict):
                messages.append({"role": "tool", "content": f"error: invalid tool call {name!r}"})
                continue
            try:
                output = tools[name](args)
            except Exception as exc:
                messages.append({"role": "tool", "content": f"error: tool {name} raised {exc}"})
                continue
            messages.append({"role": "tool", "content": str(output)})
            continue
        return _result("model_error", None, steps, tokens_used, tool_calls)
    return _result("max_steps", None, steps, tokens_used, tool_calls)

