def run_session(user_messages, assistant, tools, max_tool_retries=2, max_assistant_turns=6):
    messages = []
    outcomes = []
    tool_retries = 0
    invalid_tool_calls = 0
    failed = False
    for user_text in user_messages:
        if failed:
            outcomes.append("skipped")
            continue
        messages.append({"role": "user", "content": user_text})
        outcome = "unresolved"
        for _ in range(max_assistant_turns):
            try:
                resp = assistant(messages)
            except Exception:
                outcome = "assistant_error"
                failed = True
                break
            if not isinstance(resp, dict):
                invalid_tool_calls += 1
                messages.append({"role": "tool", "content": f"error: assistant returned non-dict {resp!r}"})
                continue
            rtype = resp.get("type")
            if rtype == "reply":
                messages.append({"role": "assistant", "content": resp.get("content", "")})
                outcome = "replied"
                break
            if rtype == "tool_call":
                name = resp.get("tool")
                args = resp.get("arguments", {})
                if name not in tools or not isinstance(args, dict):
                    invalid_tool_calls += 1
                    messages.append({"role": "tool", "content": f"error: invalid tool call {name!r}"})
                    continue
                result = None
                error = None
                attempts = 0
                while attempts <= max_tool_retries:
                    attempts += 1
                    try:
                        result = tools[name](args)
                        error = None
                        break
                    except Exception as exc:
                        error = exc
                        if attempts <= max_tool_retries:
                            tool_retries += 1
                if error is None:
                    messages.append({"role": "tool", "content": str(result)})
                    continue
                messages.append({"role": "tool", "content": f"error: tool {name} failed after {attempts} attempt(s): {error}"})
                outcome = "tool_failed"
                break
            invalid_tool_calls += 1
            messages.append({"role": "tool", "content": f"error: unknown response type {rtype!r}"})
        if failed and outcome != "assistant_error":
            outcome = "assistant_error"
        outcomes.append(outcome)
    if failed:
        status = "failed"
    elif all(o == "replied" for o in outcomes):
        status = "completed"
    else:
        status = "partial"
    return {"status": status, "messages": messages, "outcomes": outcomes,
            "tool_retries": tool_retries, "invalid_tool_calls": invalid_tool_calls}

