def execute_dag(nodes):
    for name, spec in nodes.items():
        if not isinstance(spec, dict) or not callable(spec.get("run")):
            raise ValueError(f"step {name!r} needs a callable 'run'")
        for dep in spec.get("needs", []):
            if dep not in nodes:
                raise ValueError(f"step {name!r} depends on unknown step {dep!r}")
    remaining = {name: dict(spec) for name, spec in nodes.items()}
    done = set()
    order = []
    results = {}
    while remaining:
        ready = sorted(
            name for name, spec in remaining.items()
            if all(dep in done for dep in spec.get("needs", []))
        )
        if not ready:
            cycle = ", ".join(sorted(remaining))
            raise ValueError(f"cycle detected among step(s): {cycle}")
        for name in ready:
            spec = remaining.pop(name)
            dep_results = {dep: results[dep] for dep in spec.get("needs", [])}
            results[name] = spec["run"](dep_results)
            done.add(name)
            order.append(name)
    return {"order": order, "results": results}

