import json


def parse_sse(chunks):
    events = []
    data_lines = []
    event_type = None
    buffer = ""

    def handle_line(line):
        nonlocal data_lines, event_type
        if line.endswith("\r"):
            line = line[:-1]
        if line == "":
            if data_lines:
                events.append({"event": event_type, "data": "\n".join(data_lines)})
            data_lines = []
            event_type = None
            return
        if line.startswith(":"):
            return
        field, sep, value = line.partition(":")
        if not sep:
            field, value = line, ""
        elif value.startswith(" "):
            value = value[1:]
        field = field.strip()
        if field == "data":
            data_lines.append(value)
        elif field == "event":
            event_type = value
        # id and retry are parsed but ignored

    for chunk in chunks:
        buffer += chunk
        while "\n" in buffer:
            line, buffer = buffer.split("\n", 1)
            handle_line(line)
    if buffer:
        handle_line(buffer)
    if data_lines:
        events.append({"event": event_type, "data": "\n".join(data_lines)})
    return events


def assemble_chat_stream(events):
    content = []
    finish_reason = None
    data_events = 0
    for i, event in enumerate(events):
        data = event.get("data", "") if isinstance(event, dict) else ""
        if data.strip() == "[DONE]":
            continue
        try:
            payload = json.loads(data)
        except json.JSONDecodeError:
            raise ValueError(f"malformed JSON payload in event {i}: {data!r}")
        data_events += 1
        choices = payload.get("choices", []) if isinstance(payload, dict) else []
        if not choices:
            continue
        choice = choices[0]
        delta = choice.get("delta") or {}
        text = delta.get("content")
        if text:
            content.append(text)
        reason = choice.get("finish_reason")
        if reason:
            finish_reason = reason
    return {"content": "".join(content), "finish_reason": finish_reason, "data_events": data_events}

