import copy
import re

_NAME_RE = re.compile(r"^[a-z][a-z0-9_-]{1,63}$")
_TYPES = {"string", "integer", "number", "boolean", "object", "array"}


class ToolRegistry:
    def __init__(self):
        self._tools = {}

    def register(self, schema):
        if not isinstance(schema, dict):
            raise ValueError("schema must be a dict")
        name = schema.get("name")
        if not isinstance(name, str) or not _NAME_RE.match(name):
            raise ValueError(f"invalid tool name: {name!r}")
        if name in self._tools:
            raise ValueError(f"tool already registered: {name}")
        description = schema.get("description")
        if not isinstance(description, str) or not description.strip():
            raise ValueError("description must be a non-empty string")
        input_schema = schema.get("input_schema")
        if not isinstance(input_schema, dict):
            raise ValueError("input_schema must be a dict")
        props = input_schema.get("properties", {})
        if not isinstance(props, dict):
            raise ValueError("properties must be a dict")
        for pname, pspec in props.items():
            if not isinstance(pspec, dict) or pspec.get("type") not in _TYPES:
                raise ValueError(f"property {pname!r} needs a valid 'type' in {sorted(_TYPES)}")
        required = input_schema.get("required", [])
        if not isinstance(required, list) or any((not isinstance(r, str)) or r not in props for r in required):
            raise ValueError("required must list only declared properties")
        depends_on = schema.get("depends_on", [])
        if not isinstance(depends_on, list) or any(not isinstance(d, str) for d in depends_on):
            raise ValueError("depends_on must be a list of tool names")
        self._tools[name] = {
            "name": name,
            "description": description,
            "input_schema": {"properties": copy.deepcopy(props), "required": list(required)},
            "depends_on": list(dict.fromkeys(depends_on)),
        }

    def names(self):
        return sorted(self._tools)

    def get(self, name):
        if name not in self._tools:
            raise KeyError(name)
        return copy.deepcopy(self._tools[name])

    def resolve_order(self, names=None):
        wanted = list(dict.fromkeys(names)) if names is not None else list(self._tools)
        for n in wanted:
            if n not in self._tools:
                raise ValueError(f"unknown tool: {n}")
        resolved = []
        state = {}

        def visit(n, stack):
            st = state.get(n)
            if st == "done":
                return
            if st == "visiting":
                raise ValueError(f"dependency cycle detected: {' -> '.join(stack + [n])}")
            state[n] = "visiting"
            for dep in self._tools[n]["depends_on"]:
                if dep not in self._tools:
                    raise ValueError(f"tool {n!r} depends on unknown tool {dep!r}")
                visit(dep, stack + [n])
            state[n] = "done"
            resolved.append(n)

        for n in sorted(wanted):
            visit(n, [])
        return resolved

    def validate_call(self, name, arguments):
        if name not in self._tools:
            raise KeyError(name)
        if not isinstance(arguments, dict):
            return ["arguments must be an object"]
        spec = self._tools[name]["input_schema"]
        props = spec["properties"]
        errors = []
        for req in spec["required"]:
            if req not in arguments:
                errors.append(f"missing required argument: {req}")
        for key, value in arguments.items():
            pspec = props.get(key)
            if pspec is None:
                errors.append(f"unknown argument: {key}")
                continue
            expected = pspec["type"]
            if expected == "integer":
                ok = isinstance(value, int) and not isinstance(value, bool)
            elif expected == "number":
                ok = isinstance(value, (int, float)) and not isinstance(value, bool)
            elif expected == "boolean":
                ok = isinstance(value, bool)
            elif expected == "object":
                ok = isinstance(value, dict)
            elif expected == "array":
                ok = isinstance(value, list)
            else:
                ok = isinstance(value, str)
            if not ok:
                errors.append(f"argument {key} must be of type {expected}")
        return errors

import time
import hashlib
import unicodedata
from collections import OrderedDict

_DIM = 64
_SIM_THRESHOLD = 0.9


def _normalize(text):
    text = unicodedata.normalize("NFKC", str(text))
    text = text.lower()
    return " ".join(text.split())


def _vector(text):
    vec = [0.0] * _DIM
    for tok in _normalize(text).split(" "):
        if not tok:
            continue
        digest = hashlib.md5(tok.encode("utf-8")).hexdigest()
        vec[int(digest, 16) % _DIM] += 1.0
    return vec


def _cosine(a, b):
    na = sum(x * x for x in a) ** 0.5
    nb = sum(x * x for x in b) ** 0.5
    if na == 0.0 or nb == 0.0:
        return 0.0
    return sum(x * y for x, y in zip(a, b)) / (na * nb)


class SemanticCache:
    def __init__(self, max_entries=64, ttl_seconds=None, clock=None):
        if not isinstance(max_entries, int) or max_entries <= 0:
            raise ValueError("max_entries must be a positive integer")
        if ttl_seconds is not None and ttl_seconds <= 0:
            raise ValueError("ttl_seconds must be positive")
        self.max_entries = max_entries
        self.ttl_seconds = ttl_seconds
        self.clock = clock or time.monotonic
        self._entries = OrderedDict()
        self.hits = 0
        self.misses = 0
        self.semantic_hits = 0
        self.evictions = 0

    def _key(self, prompt, model):
        return hashlib.sha256((model + "\x00" + _normalize(prompt)).encode("utf-8")).hexdigest()

    def _purge_expired(self, now):
        expired = [k for k, e in self._entries.items()
                   if e["expires"] is not None and e["expires"] <= now]
        for k in expired:
            del self._entries[k]

    def get(self, prompt, model="default"):
        now = self.clock()
        self._purge_expired(now)
        key = self._key(prompt, model)
        entry = self._entries.get(key)
        if entry is not None:
            self._entries.move_to_end(key)
            self.hits += 1
            return entry["response"]
        qvec = _vector(prompt)
        best_key = None
        best_sim = 0.0
        for k, e in self._entries.items():
            sim = _cosine(qvec, e["vector"])
            if sim > best_sim:
                best_sim = sim
                best_key = k
        if best_key is not None and best_sim >= _SIM_THRESHOLD:
            self._entries.move_to_end(best_key)
            self.hits += 1
            self.semantic_hits += 1
            return self._entries[best_key]["response"]
        self.misses += 1
        return None

    def set(self, prompt, response, model="default", ttl_seconds=None):
        now = self.clock()
        self._purge_expired(now)
        key = self._key(prompt, model)
        ttl = ttl_seconds if ttl_seconds is not None else self.ttl_seconds
        expires = now + ttl if ttl is not None else None
        if key in self._entries:
            self._entries[key]["response"] = response
            self._entries[key]["expires"] = expires
            self._entries.move_to_end(key)
            return
        self._entries[key] = {"response": response, "vector": _vector(prompt), "expires": expires}
        while len(self._entries) > self.max_entries:
            self._entries.popitem(last=False)
            self.evictions += 1

    def stats(self):
        return {"size": len(self._entries), "hits": self.hits, "misses": self.misses,
                "semantic_hits": self.semantic_hits, "evictions": self.evictions}

_DEFAULTS = {"max_error_rate_delta": 0.02, "max_error_rate_abs": 0.10,
             "max_p95_ratio": 1.25, "max_cost_ratio": 1.20, "min_samples": 50}


def _ratio(new, old):
    if old == 0:
        return 1.0 if new == 0 else float("inf")
    return round(new / old, 6)


def evaluate_canary(baseline, candidate, config=None):
    cfg = dict(_DEFAULTS)
    if config:
        cfg.update(config)
    for source, label in ((baseline, "baseline"), (candidate, "candidate")):
        if not isinstance(source, dict):
            raise ValueError(f"{label} must be a dict")
        for key in ("error_rate", "p95_latency_ms", "cost_per_request"):
            if key not in source:
                raise ValueError(f"missing metric {label}.{key}")

    samples = int(candidate.get("samples", 0))
    metrics = {
        "error_rate_delta": round(candidate["error_rate"] - baseline["error_rate"], 6),
        "p95_ratio": _ratio(candidate["p95_latency_ms"], baseline["p95_latency_ms"]),
        "cost_ratio": _ratio(candidate["cost_per_request"], baseline["cost_per_request"]),
        "samples": samples,
    }

    failures = []
    if metrics["error_rate_delta"] > cfg["max_error_rate_delta"]:
        failures.append("error_rate_regression")
    if candidate["error_rate"] > cfg["max_error_rate_abs"]:
        failures.append("error_rate_too_high")
    if metrics["p95_ratio"] > cfg["max_p95_ratio"]:
        failures.append("latency_regression")
    if metrics["cost_ratio"] > cfg["max_cost_ratio"]:
        failures.append("cost_regression")

    if samples < cfg["min_samples"]:
        decision, reason = "hold", "insufficient_data"
    elif failures:
        decision, reason = "rollback", "gate_failed"
    else:
        decision, reason = "promote", "passed"
    return {"decision": decision, "reason": reason, "failures": failures, "metrics": metrics}

