import time
from collections import deque


class TokenBucket:
    def __init__(self, capacity, refill_per_second):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        if refill_per_second < 0:
            raise ValueError("refill_per_second must be non-negative")
        self.capacity = float(capacity)
        self.refill_per_second = float(refill_per_second)
        self._tokens = self.capacity
        self._last = None

    def _refill(self, now):
        if self._last is None:
            self._last = now
            return
        elapsed = max(0.0, now - self._last)
        self._tokens = min(self.capacity, self._tokens + elapsed * self.refill_per_second)
        self._last = now

    def allow(self, tokens=1, now=None):
        if tokens <= 0:
            raise ValueError("tokens must be positive")
        now = time.monotonic() if now is None else now
        self._refill(now)
        if self._tokens >= tokens:
            self._tokens -= tokens
            return True
        return False

    def available(self, now=None):
        now = time.monotonic() if now is None else now
        if self._last is None:
            return self.capacity
        elapsed = max(0.0, now - self._last)
        return min(self.capacity, self._tokens + elapsed * self.refill_per_second)


class SlidingWindowLog:
    def __init__(self, limit, window_seconds):
        if limit <= 0:
            raise ValueError("limit must be positive")
        if window_seconds <= 0:
            raise ValueError("window_seconds must be positive")
        self.limit = int(limit)
        self.window_seconds = float(window_seconds)
        self._hits = deque()

    def _evict(self, now):
        cutoff = now - self.window_seconds
        while self._hits and self._hits[0] <= cutoff:
            self._hits.popleft()

    def allow(self, now=None):
        now = time.monotonic() if now is None else now
        self._evict(now)
        if len(self._hits) < self.limit:
            self._hits.append(now)
            return True
        return False

    def wait_time(self, now=None):
        now = time.monotonic() if now is None else now
        self._evict(now)
        if len(self._hits) < self.limit:
            return 0.0
        return max(0.0, self._hits[0] + self.window_seconds - now)

