import math
from collections import deque


class LatencyTracker:
    def __init__(self, window=200):
        if window <= 0:
            raise ValueError("window must be positive")
        self.window = window
        self._samples = deque(maxlen=window)

    def record(self, ms):
        if ms < 0:
            raise ValueError("latency must be non-negative")
        self._samples.append(float(ms))

    def percentile(self, p):
        if not 0 <= p <= 100:
            raise ValueError("p must be in [0, 100]")
        n = len(self._samples)
        if n == 0:
            return 0.0
        ordered = sorted(self._samples)
        rank = max(1, math.ceil(p / 100.0 * n))
        return ordered[rank - 1]

    def summary(self):
        n = len(self._samples)
        mean = round(sum(self._samples) / n, 4) if n else 0.0
        return {"count": n, "p50": self.percentile(50), "p95": self.percentile(95),
                "p99": self.percentile(99), "mean": mean}


def should_hedge(elapsed_ms, p95_ms, hedge_after_ratio=1.0):
    if p95_ms <= 0:
        return False
    return elapsed_ms >= p95_ms * hedge_after_ratio


def simulate_hedged_call(primary_latency_ms, hedge_latency_ms, hedge_after_ms,
                         primary_ok=True, hedge_ok=True):
    launched = primary_latency_ms > hedge_after_ms
    hedge_finish = hedge_after_ms + hedge_latency_ms
    candidates = []
    if primary_ok:
        candidates.append(("primary", primary_latency_ms))
    if launched and hedge_ok:
        candidates.append(("hedge", hedge_finish))
    errors = []
    if not primary_ok:
        errors.append("primary")
    if launched and not hedge_ok:
        errors.append("hedge")
    if candidates:
        winner, total = min(candidates, key=lambda item: item[1])
    else:
        winner = None
        total = min(primary_latency_ms, hedge_finish) if launched else primary_latency_ms
    return {"winner": winner, "hedged": launched,
            "total_latency_ms": float(total), "errors": errors}

