class LLMGateway:
    def __init__(self, bucket_capacity=10, refill_per_second=1.0, budget_usd=10.0,
                 cache_max_entries=64, clock=None):
        if bucket_capacity <= 0 or budget_usd <= 0 or cache_max_entries <= 0:
            raise ValueError("bucket_capacity, budget_usd and cache_max_entries must be positive")
        if refill_per_second < 0:
            raise ValueError("refill_per_second must be non-negative")
        self.bucket_capacity = float(bucket_capacity)
        self.refill_per_second = float(refill_per_second)
        self.budget_usd = float(budget_usd)
        self.cache_max_entries = int(cache_max_entries)
        self.clock = clock or time.monotonic
        self._tokens = self.bucket_capacity
        self._last = None
        self.spent_usd = 0.0
        self._cache = OrderedDict()
        self.cache_hits = 0
        self.blocked = 0
        self.allowed = 0

    def _refill(self, now):
        if self._last is None:
            self._last = now
            return
        elapsed = max(0.0, now - self._last)
        self._tokens = min(self.bucket_capacity, self._tokens + elapsed * self.refill_per_second)
        self._last = now

    def _key(self, prompt, model):
        return hashlib.sha256((model + "\x00" + _normalize(prompt)).encode("utf-8")).hexdigest()

    def handle(self, prompt, model="default", est_cost_usd=0.0):
        now = self.clock()
        key = self._key(prompt, model)
        cached = self._cache.get(key)
        if cached is not None:
            self._cache.move_to_end(key)
            self.cache_hits += 1
            return {"action": "cache_hit", "response": cached}
        if self.spent_usd + est_cost_usd > self.budget_usd:
            self.blocked += 1
            remaining = max(0.0, self.budget_usd - self.spent_usd)
            return {"action": "blocked_budget", "remaining_budget_usd": round(remaining, 6)}
        self._refill(now)
        if self._tokens >= 1.0:
            self._tokens -= 1.0
            self.allowed += 1
            return {"action": "call_model", "model": model}
        if self.refill_per_second <= 0:
            wait = None
        else:
            wait = round((1.0 - self._tokens) / self.refill_per_second, 4)
        return {"action": "rate_limited", "retry_after_seconds": wait}

    def complete(self, prompt, response, model="default", cost_usd=0.0, cacheable=True):
        self.spent_usd = round(self.spent_usd + cost_usd, 6)
        if cacheable:
            key = self._key(prompt, model)
            self._cache[key] = response
            self._cache.move_to_end(key)
            while len(self._cache) > self.cache_max_entries:
                self._cache.popitem(last=False)

    def stats(self):
        return {"spent_usd": round(self.spent_usd, 6), "cache_entries": len(self._cache),
                "cache_hits": self.cache_hits, "allowed": self.allowed, "blocked": self.blocked}

def compare_models(prompts, control_fn, candidate_fn, judge):
    pairs = []
    wins = losses = ties = errors = 0
    for prompt in prompts:
        try:
            control_out = control_fn(prompt)
        except Exception as exc:
            errors += 1
            pairs.append({"prompt": prompt, "control": None, "candidate": None,
                          "verdict": "control_error", "error": f"control: {exc}"})
            continue
        try:
            candidate_out = candidate_fn(prompt)
        except Exception as exc:
            errors += 1
            pairs.append({"prompt": prompt, "control": control_out, "candidate": None,
                          "verdict": "candidate_error", "error": f"candidate: {exc}"})
            continue
        verdict_raw = judge(control_out, candidate_out)
        verdict = str(verdict_raw).strip().lower() if verdict_raw is not None else ""
        if verdict not in ("candidate", "control", "tie"):
            raise ValueError(f"judge returned invalid verdict: {verdict_raw!r}")
        if verdict == "candidate":
            wins += 1
        elif verdict == "control":
            losses += 1
        else:
            ties += 1
        pairs.append({"prompt": prompt, "control": control_out,
                      "candidate": candidate_out, "verdict": verdict})

    pair_count = len(prompts)
    decidable = wins + losses + ties
    win_rate = round(wins / decidable, 4) if decidable else 0.0
    error_rate = round(errors / pair_count, 4) if pair_count else 0.0
    if pair_count == 0 or errors > pair_count * 0.2 or decidable == 0:
        decision = "inconclusive"
    elif wins > losses and win_rate >= 0.5:
        decision = "promote"
    elif wins < losses:
        decision = "block"
    else:
        decision = "hold"
    summary = {"pairs": pair_count, "candidate_wins": wins, "control_wins": losses,
               "ties": ties, "errors": errors, "decidable": decidable,
               "candidate_win_rate": win_rate, "error_rate": error_rate, "decision": decision}
    return {"pairs": pairs, "summary": summary}

