def trapped_water(heights):
    left = 0
    right = len(heights) - 1
    best_left = 0
    best_right = 0
    total = 0
    while left <= right:
        if heights[left] <= heights[right]:
            if heights[left] >= best_left:
                best_left = heights[left]
            else:
                total += best_left - heights[left]
            left += 1
        else:
            if heights[right] >= best_right:
                best_right = heights[right]
            else:
                total += best_right - heights[right]
            right -= 1
    return total

