def count_segmentations(text, words):
    dictionary = set(words)
    memo = {}

    def count(start):
        if start == len(text):
            return 1
        if start in memo:
            return memo[start]
        total = 0
        for end in range(start + 1, len(text) + 1):
            if text[start:end] in dictionary:
                total += count(end)
        memo[start] = total
        return total

    return count(0)

