def score_of_parentheses(text):
    if not text:
        raise ValueError('text must be a non-empty balanced parentheses string')
    stack = [0]
    for char in text:
        if char == '(':
            stack.append(0)
        elif char == ')':
            if len(stack) < 2:
                raise ValueError('unbalanced parentheses')
            inner = stack.pop()
            stack[-1] += max(2 * inner, 1)
        else:
            raise ValueError('only parentheses are allowed')
    if len(stack) != 1 or stack[0] == 0:
        raise ValueError('unbalanced parentheses')
    return stack[0]

