solution_code:
def top_component(rows, iterations=100):
    if not rows or not rows[0]:
        raise ValueError('rows must be non-empty')
    width = len(rows[0])
    for row in rows:
        if len(row) != width:
            raise ValueError('ragged rows')
    cov = [[0.0] * width for _ in range(width)]
    for row in rows:
        for i in range(width):
            ri = row[i]
            if ri == 0.0:
                continue
            cov_i = cov[i]
            for j in range(width):
                cov_i[j] += ri * row[j]
    vector = [1.0] * width
    norm = sum(v * v for v in vector) ** 0.5
    vector = [v / norm for v in vector]
    for _ in range(iterations):
        nxt = [sum(cov[j][k] * vector[k] for k in range(width)) for j in range(width)]
        norm = sum(v * v for v in nxt) ** 0.5
        if norm == 0.0:
            raise ValueError('degenerate covariance')
        vector = [v / norm for v in nxt]
    pivot = max(range(width), key=lambda i: abs(vector[i]))
    if vector[pivot] < 0:
        vector = [-v for v in vector]
    return [round(v, 4) for v in vector]

