def best_f1_threshold(y_true, y_scores):
    if not y_true or len(y_true) != len(y_scores):
        raise ValueError('y_true and y_scores must be non-empty and equal length')
    candidates = sorted(set(y_scores))
    positives = sum(1 for label in y_true if label == 1)
    best_f1 = 0.0
    best_threshold = candidates[-1]
    for threshold in candidates:
        tp = fp = 0
        for label, score in zip(y_true, y_scores):
            if score >= threshold:
                if label == 1:
                    tp += 1
                else:
                    fp += 1
        fn = positives - tp
        precision = tp / (tp + fp) if (tp + fp) else 0.0
        recall = tp / (tp + fn) if (tp + fn) else 0.0
        if precision + recall:
            f1 = 2 * precision * recall / (precision + recall)
        else:
            f1 = 0.0
        if f1 > best_f1 or (f1 == best_f1 and threshold > best_threshold):
            best_f1 = f1
            best_threshold = threshold
