solution_code:
def knn_impute(rows, k=3):
    if not rows:
        raise ValueError('rows must be non-empty')
    width = len(rows[0])
    for row in rows:
        if row is None or len(row) != width:
            raise ValueError('all rows must have the same width')
    complete = [i for i, row in enumerate(rows) if all(cell is not None for cell in row)]
    if not complete:
        raise ValueError('no complete row available')
    eps = 1e-6
    result = [list(row) for row in rows]
    for target_index, row in enumerate(rows):
        if all(cell is not None for cell in row):
            continue
        scored = []
        for candidate_index in complete:
            if candidate_index == target_index:
                continue
            candidate = rows[candidate_index]
            distance_sq = 0.0
            overlap = False
            for col in range(width):
                if row[col] is not None and candidate[col] is not None:
                    distance_sq += (row[col] - candidate[col]) ** 2
                    overlap = True
            if not overlap:
                continue
            scored.append((distance_sq ** 0.5, candidate_index))
        if not scored:
            raise ValueError('no overlapping candidate for an incomplete row')
        scored.sort(key=lambda item: (item[0], item[1]))
        chosen = scored[:k]
        weights = [1.0 / (distance + eps) for distance, _ in chosen]
        for col in range(width):
            if row[col] is not None:
                continue
            numerator = 0.0
            denominator = 0.0
            for (distance, candidate_index), weight in zip(chosen, weights):
                candidate_value = rows[candidate_index][col]
                numerator += weight * candidate_value
                denominator += weight
            if denominator == 0.0:
                raise ValueError('a missing cell received zero total weight')
            result[target_index][col] = round(numerator / denominator, 4)
    return result

