solution_code:
def standardize_columns(rows):
    count = len(rows)
    width = len(rows[0])
    means = [sum(row[c] for row in rows) / count for c in range(width)]
    stds = []
    for c in range(width):
        variance = sum((row[c] - means[c]) ** 2 for row in rows) / count
        stds.append(variance ** 0.5)
    out = []
    for row in rows:
        out.append([
            0.0 if stds[c] == 0 else round((row[c] - means[c]) / stds[c], 4)
            for c in range(width)
        ])
    return out

