solution_code:
def knn_classify(train_xs, train_ys, point, k):
    distances = []
    for index, row in enumerate(train_xs):
        distance = sum((a - b) ** 2 for a, b in zip(row, point))
        distances.append((distance, index))
    distances.sort(key=lambda item: (item[0], item[1]))
    neighbours = distances[:k]
    votes = {}
    for distance, index in neighbours:
        label = train_ys[index]
        votes[label] = votes.get(label, 0) + 1
    best = max(votes.values())
    tied = [label for label, count in votes.items() if count == best]
    if len(tied) == 1:
        return tied[0]
    return min(tied)

