solution_code:
def broadcast_shape(a, b):
    width = max(len(a), len(b))
    a_padded = (1,) * (width - len(a)) + tuple(a)
    b_padded = (1,) * (width - len(b)) + tuple(b)
    result = []
    for x, y in zip(a_padded, b_padded):
        if x == y:
            result.append(x)
        elif x == 1:
            result.append(y)
        elif y == 1:
            result.append(x)
        else:
            raise ValueError('incompatible shapes')
    return tuple(result)

