solution_code:
import json
import hashlib

def dataset_fingerprint(rows):
    serialized = [
        json.dumps(row, sort_keys=True, separators=(',', ':'), default=str)
        for row in rows
    ]
    blob = '\n'.join(serialized).encode('utf-8')
    return hashlib.sha256(blob).hexdigest()

