def model_card_missing(card):
    required = ['model_name', 'version', 'intended_use', 'training_data', 'evaluation', 'limitations', 'ethical_considerations', 'owners']
    missing = []
    for key in required:
        value = card.get(key)
        if key == 'evaluation':
            if not isinstance(value, dict) or not value:
                missing.append(key)
        elif key == 'owners':
            if not isinstance(value, list) or not value:
                missing.append(key)
        elif value is None or (isinstance(value, str) and not value.strip()):
            missing.append(key)
    return sorted(missing)
